const hasClass = (el, $, name) => ($(el).attr("class") ?? "").split(/\s+/).includes(name);

export const extract = ($, toMarkdown) => {
  const units = [];

  const cleanClone = (el) => {
    const clone = $(el).clone();
    clone.find("sup").remove();
    clone.find("footer").remove();
    clone.find("math").each((_, m) => {
      const alttext = $(m).attr("alttext") ?? "";
      $(m).replaceWith(alttext);
    });
    return clone;
  };

  const paragraphMarkdown = (el) => toMarkdown(cleanClone(el).get(0));

  const headingMarkdown = (el) => {
    const clone = cleanClone(el);
    const directAnchor = clone.children("a");
    if (directAnchor.length === 1 && directAnchor.text().trim() === clone.text().trim()) {
      directAnchor.replaceWith(directAnchor.contents());
    }
    return toMarkdown(clone.get(0));
  };

  const tableMarkdown = (el) => {
    const clone = cleanClone(el);
    if (clone.find("thead").length === 0) {
      const firstRow = clone.find("tr").first();
      const headerRow = $("<tr></tr>");
      firstRow.children("td").each((_, td) => {
        headerRow.append($("<th></th>").html($(td).html() ?? ""));
      });
      clone.prepend($("<thead></thead>").append(headerRow));
      firstRow.remove();
    }
    return toMarkdown(clone.get(0));
  };

  const listingMarkdown = (el) => {
    const lines = $(el)
      .children(".line")
      .map((_, line) => $(line).text())
      .get();
    const pre = $("<pre><code></code></pre>");
    pre.find("code").text(lines.join("\n"));
    return toMarkdown(pre.get(0));
  };

  const paragraph = (el) => units.push({ type: "paragraph", display: paragraphMarkdown(el), element: el });
  const heading = (el) => units.push({ type: "paragraph", display: headingMarkdown(el), element: el });

  const hasCodeInList = (el) => $(el).find("li pre").length > 0;

  const splitListAroundCode = (listEl) => {
    const tag = listEl.name;
    const items = $(listEl).children("li").toArray();
    let buffer = [];
    let emitted = 0;

    const flush = () => {
      if (buffer.length === 0) return;
      const clone = $(`<${tag}></${tag}>`);
      if (tag === "ol" && emitted > 0) {
        clone.attr("start", String(emitted + 1));
      }
      buffer.forEach((li) => clone.append($(li).clone()));
      units.push({ type: "paragraph", display: toMarkdown(clone.get(0)), element: listEl });
      emitted += buffer.length;
      buffer = [];
    };

    items.forEach((li) => {
      const pre = $(li).find("pre").first();
      if (pre.length === 0) {
        buffer.push(li);
        return;
      }
      flush();
      $(li)
        .contents()
        .each((_, child) => {
          if (child === pre.get(0)) {
            units.push({ type: "code", display: paragraphMarkdown(child), element: child });
          } else if (child.type === "tag") {
            units.push({ type: "paragraph", display: paragraphMarkdown(child), element: child });
          }
        });
      emitted += 1;
    });
    flush();
  };

  const root = $(container).first();
  const title = root.children("h1").first().text().trim();

  root.children().each((_, el) => {
    const tag = el.name;
    const $el = $(el);

    if (tag === "h1") return;
    if (hasClass(el, $, "share-buttons")) return;
    if (hasClass(el, $, "newsletter-cta")) return;
    if (hasClass(el, $, "pullquote")) return;
    if (hasClass(el, $, "sponsor-box")) return;
    if (hasClass(el, $, "ad-slot")) return;
    if (hasClass(el, $, "read-more")) return;
    if (tag === "dl") return;
    if (tag === "hr") return;
    if (tag === "ol" && hasClass(el, $, "footnotes")) return;
    if (tag === "img" && ($el.attr("src") ?? "").includes("pixel-fake")) return;

    if (tag === "p" || tag === "blockquote" || tag === "details") {
      paragraph(el);
      return;
    }

    if (tag === "div" && hasClass(el, $, "quote")) {
      paragraph(el);
      return;
    }

    if (tag === "div" && hasClass(el, $, "listing")) {
      units.push({ type: "code", display: listingMarkdown(el), element: el });
      return;
    }

    if (tag === "h2" || tag === "h3" || tag === "h4" || tag === "h5" || tag === "h6") {
      heading(el);
      return;
    }

    if (tag === "ul" || tag === "ol") {
      if (hasCodeInList(el)) {
        splitListAroundCode(el);
      } else {
        paragraph(el);
      }
      return;
    }

    if (tag === "table") {
      units.push({ type: "paragraph", display: tableMarkdown(el), element: el });
      return;
    }

    if (tag === "figure") {
      const img = $el.find("img").first();
      if (img.length > 0) {
        units.push({ type: "image", src: img.attr("src"), alt: img.attr("alt") ?? "", element: img.get(0) });
      }
      const figcaption = $el.find("figcaption").first();
      if (figcaption.length > 0) {
        paragraph(figcaption.get(0));
      }
      return;
    }

    if (tag === "img") {
      const src = $el.attr("data-src") ?? $el.attr("src");
      units.push({ type: "image", src, alt: $el.attr("alt") ?? "", element: el });
      return;
    }

    if (tag === "svg") {
      units.push({ type: "image", src: undefined, alt: $el.attr("aria-label") ?? "", element: el });
      return;
    }

    if (tag === "pre") {
      units.push({ type: "code", display: paragraphMarkdown(el), element: el });
      return;
    }

    if (tag === "math") {
      units.push({ type: "paragraph", display: $el.attr("alttext") ?? "", element: el });
      return;
    }

    throw new Error(`unhandled top-level element: <${tag} class="${$el.attr("class") ?? ""}">`);
  });

  return { title, units };
};

